/* Thèmes 1 à 3 : chapitres 1 à 13 du cours. */
(() => {
const { T, box } = OUT;

/* =================================================================== THÈME 1 */
CH(1, "Environnement économique", "L'environnement économique de l'entreprise", "Micro, méso, macro-environnement, marché, offre et demande, banques, marché financier.", `
<h3>1. L'entreprise et ses partenaires</h3>
<p>L'<b>environnement</b> est l'ensemble des éléments externes qui influencent l'entreprise, directement ou indirectement.</p>
${T(["Niveau", "Contenu", "Pouvoir de l'entreprise sur lui"], [["<b>Micro-environnement</b>", "clients, fournisseurs, concurrents, salariés, banques", "l'entreprise peut l'influencer"], ["<b>Méso-environnement</b>", "État, groupes de pression", "influence directe sur l'entreprise, peu d'influence en retour"], ["<b>Macro-environnement</b>", "contexte juridique, économique, technologique, socioculturel", "difficile à influencer"]])}
<p>Un <b>groupe de pression</b> (association de consommateurs, ONG, syndicat, organisation professionnelle) défend ses intérêts par des actions discrètes (<b>lobbying</b>) ou publiques (boycott, pétition, manifestation). L'<b>État</b> influence l'entreprise par la réglementation, les contrôles et les <b>prélèvements obligatoires</b> (impôts, taxes, cotisations sociales).</p>
<h3>2. Le marché</h3>
<p>Le <b>marché</b> est le lieu, réel ou virtuel, de rencontre entre l'<b>offre</b> (vendeurs) et la <b>demande</b> (acheteurs) d'un bien, d'un service, de travail ou de capitaux. On les classe selon la nature des échanges, la zone géographique et la périodicité.</p>
<ul><li>L'<b>offre</b> est une fonction <b>croissante</b> du prix : plus le prix monte, plus les entreprises veulent vendre.</li><li>La <b>demande</b> est une fonction <b>décroissante</b> du prix.</li><li>Le <b>prix d'équilibre</b> égalise l'offre et la demande.</li></ul>
${T(["Déséquilibre", "Situation", "Ajustement"], [["Excès d'offre", "surproduction, invendus", "le prix baisse jusqu'à l'équilibre"], ["Excès de demande", "pénurie", "le prix monte jusqu'à l'équilibre"]])}
<p>Un marché concurrentiel est favorable : baisse des prix, meilleure qualité, recherche de compétitivité.</p>
<h3>3. Les banques et le marché financier</h3>
<p>Les <b>banques</b> font de l'<b>intermédiation financière</b> (financement indirect) : elles collectent l'épargne des agents à capacité de financement et la prêtent aux agents à besoin de financement, contre des intérêts. Crédits à court terme (découvert) pour l'exploitation, à moyen et long terme pour l'investissement, mais aussi gestion de trésorerie, accompagnement à l'export, introduction en Bourse. Les TPE accèdent plus difficilement au crédit, d'où <b>Bpifrance</b>.</p>
<p>Le <b>marché financier</b> est le marché des capitaux à long terme (financement <b>direct</b>) :</p>
${T(["Compartiment", "Rôle"], [["<b>Marché primaire</b> (le « neuf »)", "émission de titres : <b>actions</b> (part du capital, droit au dividende et droit de vote : fonds propres) et <b>obligations</b> (titre de créance, intérêt fixe : endettement)"], ["<b>Marché secondaire</b> (la Bourse, « l'occasion »)", "échange de titres déjà émis : liquidité des placements, fixation du cours, rachats et fusions"]])}
${box("À retenir", "Le marché financier concerne surtout les <b>grandes entreprises</b>. Les PME se financent surtout par le crédit bancaire et l'autofinancement.", "tip")}`,
[["Les clients et les fournisseurs font partie du…", ["micro-environnement", "macro-environnement", "méso-environnement", "environnement légal"], "Ce sont les partenaires directs sur le marché."], ["La demande est une fonction ___ du prix.", ["décroissante", "croissante", "constante", "aléatoire"], "Quand le prix monte, on achète moins."], ["En cas d'excès d'offre, le prix…", ["baisse", "monte", "reste stable", "est fixé par l'État"], "Il faut écouler les invendus."], ["Un crédit bancaire est un financement…", ["indirect (intermédié)", "direct", "par fonds propres", "par le marché primaire"], "La banque est un intermédiaire."], ["Une obligation est…", ["un titre de créance rémunéré par un intérêt", "une part du capital", "un droit de vote", "une subvention"], "C'est un emprunt."], ["Le marché secondaire assure surtout…", ["la liquidité des titres", "l'émission des actions", "le crédit aux TPE", "la fixation des salaires"], "On peut revendre ses titres."]],
[{ id: "e1a", niv: 1, titre: "Classer l'environnement", q: "Une ESN lyonnaise de 40 salariés est confrontée à : 1. la hausse des taux d'intérêt de la BCE ; 2. une association de consommateurs qui dénonce ses pratiques ; 3. un nouveau concurrent sur son marché ; 4. le développement de l'IA générative ; 5. une nouvelle obligation légale de cybersécurité. Classez chaque élément (micro, méso, macro).", c: "<ol><li><b>Macro</b> (économique).</li><li><b>Méso</b> (groupe de pression).</li><li><b>Micro</b> (concurrent).</li><li><b>Macro</b> (technologique).</li><li><b>Macro</b> (juridique) — l'État qui l'impose relève du méso-environnement.</li></ol>" },
 { id: "e1b", niv: 2, titre: "Choisir un financement", q: "Une start-up veut financer : a) un décalage de trésorerie de 3 semaines ; b) l'achat de serveurs pour 200 000 € ; c) une forte croissance sans s'endetter. Quelles solutions proposer ?", c: "<ol><li><b>Découvert</b> ou crédit court terme (besoin court et limité).</li><li><b>Emprunt</b> bancaire à moyen terme (ou crédit-bail).</li><li><b>Augmentation de capital</b> : levée de fonds auprès d'investisseurs (business angels, capital-risque), soit des fonds propres sans endettement, mais avec dilution du pouvoir des fondateurs.</li></ol>" }]);

CH(1, "Interactions et marché", "Les interactions entre l'entreprise et son environnement économique", "Concurrence, coopération, information, externalités.", `
<h3>1. Concurrence et coopération</h3>
<p>La <b>concurrence</b> est la compétition entre entreprises d'un marché, par les prix ou par les caractéristiques des produits. Son intensité dépend du nombre d'entreprises :</p>
${T(["Structure", "Nombre d'offreurs", "Exemple"], [["Concurrence", "nombreux", "restauration, développement web freelance"], ["<b>Oligopole</b>", "quelques-uns", "opérateurs télécoms, cloud public"], ["<b>Monopole</b>", "un seul", "réseau ferré"]])}
<p>Peu de concurrence = prix trop élevés. L'<b>Autorité de la concurrence</b> (autorité administrative indépendante) contrôle les pratiques anticoncurrentielles : avis, injonctions, sanctions pécuniaires.</p>
<p>La <b>coopération</b> permet d'atteindre une taille critique (matières premières, savoir-faire, innovation, financement) : <b>alliance</b> entre concurrents (Renault-Nissan), <b>partenariat</b> entre non-concurrents (client-fournisseur). Attention : une coopération qui fausse le marché devient une <b>entente</b> illicite.</p>
<h3>2. L'information sur le marché</h3>
<p>Le marché ne fonctionne bien que si l'information est <b>fiable</b>. Les avis en ligne et l'<b>e-réputation</b> pèsent sur les décisions d'achat. L'information peut être <b>manipulée</b> (faux avis, dénigrement, opacité sur la provenance) : la confiance se dégrade. L'État encadre par des normes et la <b>DGCCRF</b> veille à la loyauté de l'information et aux droits des consommateurs.</p>
<h3>3. Les externalités</h3>
<p>Une <b>externalité</b> est l'effet de l'activité d'un agent sur le bien-être d'un autre <b>sans compensation monétaire</b> : le marché ne la prend pas en compte.</p>
${T(["Type", "Exemple", "Réponse"], [["<b>Positive</b>", "un incubateur qui profite à tout un quartier, un logiciel libre", "pas de contrepartie financière, mais gain d'image (RSE)"], ["<b>Négative</b>", "pollution, consommation énergétique des data centers", "taxes, normes, malus, sanctions ; l'entreprise modifie son activité"]])}`,
[["Un marché avec quelques entreprises est un…", ["oligopole", "monopole", "marché concurrentiel", "monopsone"], "Exemple : la téléphonie mobile en France."], ["Quelle autorité contrôle les ententes en France ?", ["l'Autorité de la concurrence", "la CNIL", "l'ARCOM", "l'INPI"], "C'est une autorité administrative indépendante."], ["Une alliance réunit…", ["des entreprises concurrentes", "un client et son fournisseur", "l'État et une entreprise", "des salariés"], "Le partenariat réunit des non-concurrents."], ["La pollution d'une usine est une…", ["externalité négative", "externalité positive", "entente", "barrière à l'entrée"], "Les riverains la subissent sans compensation."], ["Quel organisme veille à la loyauté de l'information pour les consommateurs ?", ["la DGCCRF", "l'INPI", "Bpifrance", "l'URSSAF"], "Direction générale de la concurrence, de la consommation et de la répression des fraudes."], ["Les faux avis clients posent un problème de…", ["fiabilité de l'information", "externalité positive", "coût fixe", "liquidité"], "Ils faussent le fonctionnement du marché."]],
[{ id: "e2a", niv: 2, titre: "Externalités du numérique", q: "Une entreprise d'hébergement construit un data center qui récupère sa chaleur pour chauffer une piscine municipale, mais consomme beaucoup d'électricité et d'eau. Identifiez les externalités et expliquez comment l'entreprise peut les gérer.", c: "<p><b>Externalité positive</b> : la chaleur récupérée profite à la commune sans paiement (si elle est gratuite). <b>Externalités négatives</b> : consommation d'énergie et d'eau, pression sur les ressources locales, émissions indirectes.</p><p>Gestion : réduire (refroidissement plus efficace, énergie renouvelable), communiquer sur ses actions dans une démarche <b>RSE</b> (gain d'image), anticiper les taxes et normes environnementales.</p>" }]);

CH(1, "Le contrat", "Le contrat, un outil qui sécurise l'entreprise", "Pourparlers, validité, clauses, effets, inexécution, responsabilité contractuelle.", `
<h3>1. Avant le contrat</h3>
<p>Les <b>pourparlers</b> sont libres (aucune obligation de conclure) mais doivent respecter la <b>bonne foi</b> (art. 1112 C. civ.), le <b>devoir d'information</b> (art. 1112-1) et la <b>confidentialité</b>. Une rupture fautive donne lieu à des dommages-intérêts couvrant les frais engagés, <b>pas</b> le gain espéré du contrat.</p>
<ul><li><b>Pacte de préférence</b> (art. 1123) : on s'engage à proposer d'abord le bien à une personne si on décide de vendre.</li><li><b>Promesse unilatérale</b> (art. 1124) : le promettant s'engage déjà ; le bénéficiaire a une option pour décider plus tard.</li></ul>
<h3>2. La formation du contrat (art. 1128)</h3>
${T(["Condition de validité", "Contenu"], [["<b>Consentement</b>", "rencontre d'une offre et d'une acceptation ; il doit être <b>libre et éclairé</b>, sans vice : <b>erreur</b> (sur une qualité essentielle), <b>dol</b> (manœuvre ou mensonge pour tromper, art. 1137), <b>violence</b> (physique, morale, ou abus de dépendance)"], ["<b>Capacité</b>", "pas de mineur ni de majeur protégé (sauf actes courants) ; pour une personne morale, un représentant habilité"], ["<b>Contenu licite et certain</b>", "conforme à l'ordre public, prestation existante ou future et déterminée"]])}
<p>Sanction : la <b>nullité</b> (le contrat est censé n'avoir jamais existé ; on remet les parties dans leur état antérieur). <b>Relative</b> si elle protège un intérêt privé (vice du consentement : seule la victime l'invoque) ; <b>absolue</b> si elle protège l'intérêt général (objet illicite : toute personne intéressée).</p>
<h3>3. Les clauses utiles</h3>
${T(["Clause", "Effet"], [["Réserve de propriété", "le vendeur reste propriétaire jusqu'au paiement complet"], ["Limitative de responsabilité", "plafonne l'indemnité ; sans effet si elle vide l'obligation essentielle (art. 1170), en cas de faute lourde ou dolosive, ou pour les dommages corporels"], ["Pénale", "fixe à l'avance la pénalité en cas d'inexécution (ex. : pénalités de retard)"], ["Résolutoire", "fin du contrat sans juge en cas de manquement précis, après mise en demeure"], ["Indexation", "le prix évolue selon un indice"], ["Confidentialité, SLA (niveau de service)", "très fréquentes dans les contrats informatiques"]])}
<h3>4. Les effets du contrat</h3>
<ul><li><b>Force obligatoire</b> (art. 1103) : le contrat est la loi des parties ; il ne peut être modifié que d'un commun accord (art. 1193). Exception : l'<b>imprévision</b> (art. 1195) permet de demander une renégociation si un changement imprévisible rend l'exécution excessivement onéreuse.</li><li><b>Effet relatif</b> (art. 1199) : le contrat ne crée d'obligations qu'entre les parties, pas pour les tiers.</li></ul>
<h3>5. L'inexécution (art. 1217)</h3>
${T(["Sanction", "Principe"], [["<b>Exception d'inexécution</b> (art. 1219-1220)", "suspendre sa propre obligation si l'autre n'exécute pas la sienne (inexécution suffisamment grave)"], ["<b>Exécution forcée en nature</b> (art. 1221)", "après mise en demeure, sauf impossibilité ou coût disproportionné"], ["<b>Réduction du prix</b>", "en cas d'exécution imparfaite"], ["<b>Résolution</b> (art. 1224)", "anéantit le contrat, avec restitutions ; la <b>résiliation</b> ne vaut que pour l'avenir"], ["<b>Dommages-intérêts</b> (art. 1231-1)", "réparation de la perte subie et du gain manqué"]])}
${box("Responsabilité contractuelle : 3 conditions", "<b>Un fait générateur</b> (inexécution fautive ; pour une <b>obligation de résultat</b>, il suffit que le résultat ne soit pas atteint ; pour une <b>obligation de moyens</b>, le créancier doit prouver que le débiteur n'a pas tout mis en œuvre), <b>un dommage</b>, <b>un lien de causalité</b>. Exonération : <b>force majeure</b> (art. 1218 : événement échappant au contrôle du débiteur, imprévisible et irrésistible), fait d'un tiers ou fait du créancier.", "tip")}`,
[["Les pourparlers obligent-ils à conclure le contrat ?", ["Non, mais ils doivent être menés de bonne foi", "Oui, toujours", "Oui, s'ils durent plus d'un mois", "Non, et aucune règle ne s'applique"], "Art. 1112 du Code civil."], ["Un mensonge destiné à tromper le cocontractant est…", ["un dol", "une erreur", "une violence", "une clause pénale"], "Art. 1137 du Code civil."], ["Un contrat conclu par un mineur pour un achat important est…", ["annulable (nullité relative)", "valable", "nul de nullité absolue", "résilié"], "Défaut de capacité : on protège le mineur."], ["La clause qui fixe à l'avance une pénalité de retard est une clause…", ["pénale", "résolutoire", "de réserve de propriété", "d'indexation"], "Elle évite d'avoir à chiffrer le préjudice."], ["La résolution d'un contrat…", ["l'anéantit avec effet rétroactif", "ne vaut que pour l'avenir", "le prolonge", "le transforme"], "La résiliation, elle, ne vaut que pour l'avenir."], ["Pour une obligation de résultat, le créancier doit prouver…", ["seulement que le résultat n'est pas atteint", "la faute du débiteur", "l'intention de nuire", "rien du tout"], "La faute est présumée."], ["Quelle exonération suppose un événement imprévisible et irrésistible ?", ["la force majeure", "la clause pénale", "l'effet relatif", "l'imprévision"], "Art. 1218 du Code civil."]],
[{ id: "e3a", niv: 2, titre: "Vice du consentement", q: "La société WebNova achète un logiciel de gestion à un éditeur. Le commercial lui a affirmé que le logiciel était « compatible RGPD et hébergé en France ». WebNova découvre que les données sont hébergées hors de l'Union européenne, ce que le commercial savait. Peut-elle obtenir l'annulation ? Rédigez un syllogisme.", c: "<p><b>Problème juridique :</b> un contrat conclu sur la base d'une fausse information volontairement donnée par le vendeur peut-il être annulé ?</p><p><b>Règle :</b> le consentement doit être libre et éclairé (art. 1128 C. civ.). Le <b>dol</b> est le fait d'obtenir le consentement de l'autre par des manœuvres ou des mensonges (art. 1137) ; il entraîne la <b>nullité relative</b> du contrat, que seule la victime peut demander, et peut ouvrir droit à des dommages-intérêts.</p><p><b>Application :</b> le commercial a menti sur un élément déterminant (lieu d'hébergement et conformité RGPD), en connaissance de cause, et WebNova n'aurait pas contracté si elle avait su.</p><p><b>Conclusion :</b> WebNova peut demander la nullité du contrat pour dol, et des dommages-intérêts.</p>" },
 { id: "e3b", niv: 3, titre: "Inexécution d'un contrat de prestation", q: "Une ESN s'est engagée par contrat à livrer un site e-commerce le 1er mars, avec une clause prévoyant 200 € de pénalité par jour de retard. Le site est livré le 21 mars. Le client a perdu des ventes. L'ESN invoque une grève de ses propres salariés. Analysez la situation.", c: "<p><b>Problème :</b> l'ESN peut-elle s'exonérer de sa responsabilité contractuelle pour retard en invoquant une grève de son personnel ?</p><p><b>Règles :</b> le contrat a force obligatoire (art. 1103). En cas d'inexécution, le créancier peut demander des dommages-intérêts (art. 1217 et 1231-1). La responsabilité contractuelle suppose un fait générateur, un dommage et un lien de causalité. Une <b>clause pénale</b> fixe la pénalité à l'avance. Le débiteur s'exonère par la <b>force majeure</b> (art. 1218), événement échappant à son contrôle, imprévisible et irrésistible.</p><p><b>Application :</b> livrer à une date précise est une obligation de résultat, non atteinte : 20 jours de retard. Une grève interne à l'entreprise n'est en général pas extérieure à elle ni forcément irrésistible : ce n'est pas un cas de force majeure.</p><p><b>Conclusion :</b> l'ESN est responsable ; elle doit la pénalité prévue, soit 20 × 200 = <b>4 000 €</b> (le juge peut la modérer si elle est manifestement excessive ou dérisoire).</p>" }]);

CH(1, "Finalités et parties prenantes", "Le rôle de l'environnement : finalités, parties prenantes, entreprendre", "Finalités, RSE, objectifs, parties prenantes, performance, entrepreneur et manager.", `
<h3>1. Les finalités</h3>
<p>La <b>finalité</b> est la raison d'être de l'entreprise. Elle dépend des dirigeants, des actionnaires, de l'histoire, du personnel et de l'environnement.</p>
<ul><li><b>Économique</b> (ou financière) : produire des biens et services rentables, faire du profit.</li><li><b>Sociale</b> : assurer l'emploi, de bonnes conditions de travail.</li><li><b>Sociétale</b> : tenir compte de l'impact sur l'environnement et la société → <b>RSE</b> (responsabilité sociétale des entreprises).</li></ul>
<p>Obligations liées : <b>bilan social</b> à partir de 300 salariés ; reporting extra-financier des grandes entreprises (loi Grenelle II de 2010, aujourd'hui renforcé par le droit européen).</p>
<p>Les <b>objectifs</b> déclinent la finalité : individuels ou collectifs ; de <b>performance</b> (+3 % de chiffre d'affaires) ou de <b>fonctionnement</b> (moins d'accidents du travail) ; <b>stratégiques</b> (long terme) ou <b>opérationnels</b> (court terme).</p>
<h3>2. Les parties prenantes</h3>
<p>Une <b>partie prenante</b> influence l'entreprise ou est affectée par ses décisions : interdépendance. <b>Premier rang</b> (relation directe et forte influence : salariés, actionnaires, clients, fournisseurs, banques) et <b>second rang</b> (associations, collectivités, médias, riverains). Leurs attentes peuvent être contradictoires : le dirigeant arbitre.</p>
<h3>3. La performance</h3>
${T(["Notion", "Compare", "Question"], [["<b>Pertinence</b>", "moyens / objectifs", "les moyens choisis sont-ils adaptés ?"], ["<b>Efficacité</b>", "résultats / objectifs", "a-t-on atteint l'objectif ?"], ["<b>Efficience</b>", "résultats / moyens", "a-t-on atteint le résultat au moindre coût ?"]])}
<p>Formes de performance : <b>économique</b> (rentabilité, marge), <b>organisationnelle</b> (structure adaptée aux objectifs), <b>sociale</b> (conditions de travail, satisfaction), <b>environnementale</b>.</p>
<h3>4. Entreprendre et manager</h3>
<p>Créer : diagnostic de l'environnement (opportunités, menaces), recherche de fonds, choix d'une structure juridique, organisation, le tout formalisé dans un <b>business plan</b>.</p>
${T(["Logique entrepreneuriale", "Logique managériale"], [["recherche d'opportunités, vision à long terme, goût du risque, capacité à fédérer", "allocation optimale des ressources, continuité de l'exploitation, gestion courante"]])}
<p>Les deux logiques sont <b>complémentaires</b> : dans une petite entreprise, l'entrepreneur est aussi le manager ; un manager prend parfois des décisions stratégiques.</p>`,
[["Comparer les résultats obtenus aux objectifs, c'est mesurer…", ["l'efficacité", "l'efficience", "la pertinence", "la rentabilité"], "Efficience : résultats / moyens."], ["La RSE relève de la finalité…", ["sociétale", "uniquement financière", "fiscale", "juridique"], "Prise en compte de l'environnement et de la société."], ["Un riverain d'une usine est une partie prenante de…", ["second rang", "premier rang", "aucun rang", "rang hiérarchique"], "Influence plus faible, pas de relation contractuelle."], ["La logique managériale vise surtout…", ["l'allocation optimale des ressources", "la prise de risque", "la création d'entreprise", "la recherche d'opportunités"], "Le manager assure le bon fonctionnement."], ["Le document qui présente un projet de création aux financeurs est…", ["le business plan", "le bilan social", "le règlement intérieur", "le Kbis"], "Plan d'affaires."], ["« Réduire de 20 % les accidents du travail » est un objectif de…", ["fonctionnement", "performance financière", "rentabilité", "part de marché"], "Il vise le bien-être dans l'organisation."]],
[{ id: "e4a", niv: 2, titre: "Analyser la performance", q: "Une ESN s'était fixé 2 M€ de chiffre d'affaires. Elle réalise 2,2 M€ mais a dû embaucher 10 développeurs en urgence et recourir massivement à des freelances coûteux : sa marge a fortement baissé. Analysez sa performance.", c: "<p><b>Efficace</b> : l'objectif de chiffre d'affaires est dépassé (2,2 M€ contre 2 M€). <b>Peu efficiente</b> : les moyens utilisés ont coûté cher et la marge baisse. La <b>pertinence</b> des moyens peut être discutée : une meilleure anticipation des recrutements (GPEC) aurait évité le recours aux freelances. La performance économique est donc mitigée.</p>" }]);

/* =================================================================== THÈME 2 */
CH(2, "La croissance", "La croissance", "PIB, valeur ajoutée, productivité, innovation (Schumpeter), inflation, chômage.", `
<h3>1. Mesurer la richesse</h3>
<p>Le <b>PIB</b> (produit intérieur brut) mesure la richesse produite sur un territoire pendant une période. Il additionne les <b>valeurs ajoutées</b> :</p>
${box("Formule", "<b>Valeur ajoutée = chiffre d'affaires (production) − consommations intermédiaires.</b> La production non marchande des administrations est évaluée à son coût de production.")}
<p>La <b>croissance économique</b> est l'augmentation durable du PIB (en volume, c'est-à-dire hors inflation). Évolution en France : <b>tertiairisation</b> (les services dominent), <b>désindustrialisation</b>, recul de l'agriculture.</p>
<h3>2. Les facteurs de croissance</h3>
<ul><li><b>Le travail</b> : quantité (population active, durée du travail) et qualité (<b>capital humain</b> : formation, compétences).</li><li><b>Le capital</b> : l'accumulation d'équipements, qui intègrent le progrès technique.</li><li><b>La productivité</b> : production / facteurs utilisés. Les gains de productivité permettent de produire plus avec autant de ressources, et de distribuer des revenus qui créent une nouvelle demande.</li></ul>
<h3>3. L'innovation selon Schumpeter</h3>
<p>L'innovation est le moteur de la croissance. Elle provoque une <b>destruction créatrice</b> (les nouvelles activités remplacent les anciennes) et arrive en <b>grappes</b>. Cinq formes : nouveaux <b>produits</b> (objets connectés), nouveaux <b>procédés</b> (conception 3D), nouvelles <b>organisations</b> de la production (juste-à-temps, lean), nouveaux <b>débouchés</b> (l'ordinateur des entreprises vers les particuliers), nouvelles <b>matières premières</b> (plastique recyclé).</p>
<h3>4. L'entreprise face à la conjoncture</h3>
<ul><li>L'État soutient la croissance (plans d'investissement : numérique, transition écologique, compétences).</li><li><b>Inflation</b> (hausse générale et durable des prix) : baisse du pouvoir d'achat des consommateurs et de la valeur de l'épargne, allègement réel des dettes ; hausse des coûts des entreprises.</li><li><b>Chômage</b> élevé : moins de pression sur les salaires mais moins de pouvoir d'achat ; chômage bas : difficultés de recrutement sur les métiers en tension (le numérique en fait partie).</li></ul>`,
[["Valeur ajoutée =", ["chiffre d'affaires − consommations intermédiaires", "chiffre d'affaires − salaires", "bénéfice + impôts", "production + importations"], "C'est la richesse réellement créée par l'entreprise."], ["Selon Schumpeter, le moteur de la croissance est…", ["l'innovation", "l'inflation", "la dépense publique", "le protectionnisme"], "D'où la destruction créatrice."], ["Le passage au cloud qui fait disparaître des métiers de maintenance et en crée d'autres illustre…", ["la destruction créatrice", "l'inflation", "l'externalité positive", "l'entente"], "Notion clé de Schumpeter."], ["La tertiairisation désigne…", ["la part croissante des services dans l'économie", "le passage à 3 associés", "la hausse de l'industrie", "la baisse des services"], "Les services dominent le PIB."], ["Les gains de productivité permettent…", ["de produire plus avec les mêmes ressources", "d'augmenter forcément le chômage", "de baisser le PIB", "de supprimer le capital"], "Productivité = production / facteurs."], ["L'inflation allège…", ["la charge réelle des dettes", "le pouvoir d'achat", "la valeur de l'épargne", "les coûts des entreprises"], "Les remboursements valent moins en termes réels."]],
[{ id: "e5a", niv: 1, titre: "Calculer une valeur ajoutée", q: "Une société de développement web réalise 850 000 € de chiffre d'affaires. Elle a acheté pour 120 000 € de licences, 45 000 € d'hébergement et 35 000 € de sous-traitance graphique. Elle verse 400 000 € de salaires. Calculez sa valeur ajoutée.", c: "<p>Consommations intermédiaires = 120 000 + 45 000 + 35 000 = 200 000 €. <b>Valeur ajoutée = 850 000 − 200 000 = 650 000 €.</b> Les salaires ne sont pas des consommations intermédiaires : ils sont payés à partir de la valeur ajoutée (partage de la VA entre salariés, État, prêteurs, actionnaires, entreprise).</p>" }]);

CH(2, "Rôle de l'État", "Le rôle de l'État et ses limites", "Politiques conjoncturelle et structurelle, Bpifrance, APE, régulation européenne.", `
<h3>1. L'État au cœur de l'activité des entreprises</h3>
${T(["Politique", "Objectif", "Outils et effets"], [["<b>Conjoncturelle</b> (court terme)", "relancer l'activité ou freiner la surchauffe", "<b>politique budgétaire</b> : la dépense publique remplit les carnets de commandes (<b>effet multiplicateur</b>) ; mais elle est financée par des prélèvements obligatoires qui pèsent sur la compétitivité. <b>Politique monétaire</b> : taux d'intérêt fixés par la BCE"], ["<b>Structurelle</b> (long terme)", "améliorer durablement l'économie", "biens publics (éducation, santé, infrastructures, réseaux), politique industrielle, recherche, formation"]])}
<p>L'État corrige aussi les <b>défaillances du marché</b> : externalités (taxes, normes), biens publics que le marché ne produit pas, concurrence insuffisante (régulation), information imparfaite.</p>
<h3>2. Les limites de l'État</h3>
<ul><li>Face aux <b>délocalisations</b> et fermetures d'usines, les aides publiques (subventions des collectivités) ne garantissent pas le maintien de l'activité.</li><li>Soutien par ses organismes : <b>Bpifrance</b> (prêts, garanties, fonds propres, innovation, export), <b>APE</b> (Agence des participations de l'État : l'État actionnaire d'entreprises stratégiques).</li><li>Effets pervers : optimisation fiscale des multinationales du numérique, excès de réglementation qui décourage l'investissement.</li></ul>
<h3>3. La régulation supranationale</h3>
<p>Des décisions prises « au-dessus » de l'État orientent la stratégie des entreprises : <b>Commission européenne</b> et <b>Conseil</b> (autorisations, normes, droit de la concurrence), <b>BCE</b> (taux d'intérêt de la zone euro), accords commerciaux (CETA avec le Canada). Pour le numérique : RGPD, DMA et DSA (règles imposées aux grandes plateformes), règlement sur l'IA.</p>`,
[["Augmenter la dépense publique pour relancer l'activité relève de la politique…", ["budgétaire (conjoncturelle)", "structurelle", "monétaire", "de la concurrence"], "Effet multiplicateur."], ["Qui fixe les taux directeurs dans la zone euro ?", ["la BCE", "le gouvernement français", "Bpifrance", "la Commission européenne"], "Banque centrale européenne."], ["Construire des réseaux de fibre optique relève d'une politique…", ["structurelle", "conjoncturelle", "monétaire", "salariale"], "Effet à long terme sur l'économie."], ["Bpifrance sert à…", ["financer et accompagner les entreprises, notamment les PME", "contrôler les ententes", "fixer le SMIC", "protéger les données"], "Banque publique d'investissement."], ["L'effet multiplicateur désigne…", ["l'effet amplifié d'une dépense publique sur la production", "la hausse des impôts", "la création de monnaie par la BCE", "la multiplication des normes"], "Une dépense crée des revenus qui sont dépensés à leur tour."]],
[{ id: "e6a", niv: 2, titre: "État et numérique", q: "Expliquez comment l'État et l'Union européenne peuvent à la fois aider et contraindre une start-up française du cloud.", c: "<p><b>Aider</b> : financement et garanties de Bpifrance, crédit d'impôt recherche, commande publique (hébergement de données publiques sensibles), infrastructures (fibre), formation de développeurs, règles européennes qui limitent la puissance des géants (DMA) et ouvrent le marché.</p><p><b>Contraindre</b> : prélèvements obligatoires, obligations RGPD et de cybersécurité (NIS2), normes environnementales, coût de la mise en conformité.</p>" }]);

CH(2, "Droit de la concurrence", "La régulation des activités économiques par le droit", "Concurrence déloyale, pratiques restrictives, ententes, abus de position dominante, brevet, marque.", `
<h3>1. Les comportements déloyaux</h3>
<p>La <b>concurrence déloyale</b> repose sur la responsabilité délictuelle (<b>art. 1240 C. civ.</b>) : une <b>faute</b> (comportement déloyal), un <b>dommage</b> (perte de clientèle, atteinte à l'image) et un <b>lien de causalité</b>.</p>
${T(["Acte", "Définition"], [["<b>Dénigrement</b>", "jeter le discrédit sur les produits d'un concurrent"], ["<b>Désorganisation</b>", "perturber l'organisation d'un concurrent (débauchage massif, embauche d'un salarié tenu par une clause de non-concurrence)"], ["<b>Imitation / confusion</b>", "copier le nom, le logo, les produits pour créer une confusion"], ["<b>Parasitisme</b>", "profiter sans frais de la notoriété ou des investissements d'une autre entreprise, même non concurrente"]])}
<p><b>Pratiques restrictives</b> (Code de commerce), interdites même sans effet sur tout le marché : <b>revente à perte</b> (art. L. 442-5, sauf exceptions comme les soldes), <b>rupture brutale</b> d'une relation commerciale établie sans préavis suffisant (art. L. 442-1).</p>
<h3>2. Les pratiques anticoncurrentielles</h3>
${T(["Pratique", "Texte", "Exemple"], [["<b>Entente</b> (horizontale entre concurrents ou verticale entre fournisseur et distributeur)", "art. L. 420-1 C. com. ; art. 101 TFUE", "accord sur les prix, partage du marché ou des clients"], ["<b>Abus de position dominante</b>", "art. L. 420-2 C. com. ; art. 102 TFUE", "vente liée, prix d'éviction, refus d'accès"]])}
<p>Trois conditions pour l'abus : une <b>position dominante</b> (pouvoir d'imposer sa volonté au marché), un <b>abus</b>, un <b>effet</b> restrictif sur la concurrence. Avoir une position dominante n'est pas interdit : c'est l'abus qui l'est.</p>
<p>Les <b>concentrations</b> (fusions, rachats) importantes sont contrôlées à l'avance. L'<b>Autorité de la concurrence</b> (AAI) enquête, rend des avis, prononce des injonctions et des sanctions (jusqu'à 10 % du chiffre d'affaires mondial). Au niveau européen : la Commission européenne.</p>
<h3>3. La propriété industrielle</h3>
${T(["", "Brevet", "Marque"], [["Protège", "une <b>invention</b> nouvelle, inventive, susceptible d'application industrielle", "un <b>signe distinctif</b> (verbal, figuratif, semi-figuratif)"], ["Durée", "<b>20 ans</b>, non renouvelable, puis domaine public", "<b>10 ans</b>, renouvelable indéfiniment"], ["Dépôt", "INPI", "INPI (EUIPO pour l'UE)"], ["Limite", "coûteux, oblige à divulguer l'invention", "doit être distinctive (pas un nom générique)"]])}
<p>L'atteinte à ces droits est une <b>contrefaçon</b> : sanctions pénales et dommages-intérêts.</p>
${box("Pour l'informatique", "Un logiciel en tant que tel n'est en principe <b>pas brevetable</b> en Europe : il est protégé par le <b>droit d'auteur</b> (voir thème 4).", "tip")}`,
[["La concurrence déloyale se fonde sur…", ["la responsabilité délictuelle (art. 1240 C. civ.)", "le contrat", "le droit pénal uniquement", "le RGPD"], "Faute, dommage, lien de causalité."], ["Profiter de la notoriété d'une entreprise non concurrente s'appelle…", ["le parasitisme", "le dénigrement", "l'entente", "la désorganisation"], "Pas besoin d'être concurrent."], ["Un accord secret entre concurrents sur les prix est…", ["une entente illicite", "un partenariat légal", "un abus de position dominante", "du parasitisme"], "Art. L. 420-1 du Code de commerce."], ["Avoir une position dominante est…", ["autorisé ; c'est l'abus qui est interdit", "toujours interdit", "puni de prison", "réservé à l'État"], "Il faut un abus et un effet sur la concurrence."], ["Durée de protection d'un brevet :", ["20 ans", "10 ans renouvelables", "70 ans après la mort", "5 ans"], "Puis l'invention tombe dans le domaine public."], ["Une marque est protégée…", ["10 ans, renouvelables indéfiniment", "20 ans non renouvelables", "à vie", "1 an"], "D'où un avantage potentiellement permanent."], ["Une marque « Ordinateur » pour vendre des ordinateurs est…", ["refusée car non distinctive", "acceptée", "acceptée pour 5 ans", "un brevet"], "Un nom générique ne peut pas être une marque pour ce produit."]],
[{ id: "e7a", niv: 3, titre: "Concurrence déloyale", q: "La start-up CloudLy découvre qu'un concurrent publie sur LinkedIn des messages affirmant que « CloudLy perd les données de ses clients », sans aucune preuve. Plusieurs prospects ont renoncé à signer. Que peut faire CloudLy ? Rédigez un syllogisme.", c: "<p><b>Problème :</b> une entreprise qui critique publiquement et sans fondement un concurrent engage-t-elle sa responsabilité ?</p><p><b>Règle :</b> l'action en concurrence déloyale repose sur l'article 1240 du Code civil : tout fait fautif qui cause un dommage à autrui oblige son auteur à le réparer. Il faut une faute (ici le <b>dénigrement</b> : jeter le discrédit sur les produits d'un concurrent), un dommage et un lien de causalité.</p><p><b>Application :</b> la faute est le dénigrement (affirmations fausses, publiques, visant les services de CloudLy). Le dommage est la perte de prospects et l'atteinte à l'image. Le lien de causalité est établi si les prospects ont renoncé à cause de ces messages (à prouver : e-mails, témoignages).</p><p><b>Conclusion :</b> CloudLy peut agir en concurrence déloyale pour obtenir des dommages-intérêts et la suppression des messages.</p>" },
 { id: "e7b", niv: 2, titre: "Abus de position dominante", q: "Un éditeur détient 80 % du marché des logiciels de caisse pour la restauration. Il impose à ses clients d'utiliser uniquement son propre terminal de paiement, sinon il coupe les mises à jour. Analysez.", c: "<p>Conditions de l'abus (art. L. 420-2 C. com., art. 102 TFUE) : 1) <b>position dominante</b> : 80 % du marché, les restaurateurs peuvent difficilement changer ; 2) <b>abus</b> : vente liée et menace de couper les mises à jour ; 3) <b>effet sur la concurrence</b> : les fabricants de terminaux concurrents sont évincés. Les trois conditions semblent réunies : l'Autorité de la concurrence peut prononcer une injonction et une sanction pécuniaire.</p>" }]);

CH(2, "Environnement global", "L'environnement global de l'entreprise", "PESTEL, instabilité de l'environnement, opportunités et menaces.", `
<h3>1. Le macro-environnement et le PESTEL</h3>
<p>L'<b>environnement global</b> regroupe les variables qui ne dépendent pas de l'entreprise mais l'influencent. On l'analyse avec le <b>PESTEL</b> :</p>
${T(["Facteur", "Exemples pour une entreprise du numérique"], [["<b>P</b>olitique", "stabilité politique, souveraineté numérique, commande publique, tensions géopolitiques"], ["<b>É</b>conomique", "croissance, inflation, taux d'intérêt, pouvoir d'achat, coût de l'énergie"], ["<b>S</b>ocioculturel", "télétravail, attentes des jeunes générations, démographie, défiance envers les réseaux sociaux"], ["<b>T</b>echnologique", "IA générative, cloud, 5G, cybermenaces"], ["<b>É</b>cologique", "sobriété numérique, empreinte carbone, recyclage du matériel"], ["<b>L</b>égal", "RGPD, NIS2, règlement européen sur l'IA, droit du travail"]])}
${box("Conseil", "Le classement d'un élément dans tel ou tel facteur n'est pas l'essentiel : le PESTEL sert surtout à être <b>complet</b>. Pour chaque élément, dis s'il est une <b>opportunité</b> ou une <b>menace</b> pour l'entreprise étudiée.", "tip")}
<h3>2. Un environnement instable</h3>
<p>L'environnement est <b>instable</b> (il change vite), <b>incertain</b> (difficile à prévoir) et <b>complexe</b> (nombreux facteurs simultanés). Certaines mutations viennent de l'action publique (lois, institutions internationales), d'autres des citoyens et consommateurs (modes de vie, consommateurs volatils).</p>
<h3>3. Opportunités et menaces</h3>
<p>Un même élément peut être à la fois une opportunité et une menace (hausse du pouvoir d'achat : plus de ventes, mais attire des concurrents et éloigne des produits d'entrée de gamme). L'entreprise doit <b>veiller</b> sur son environnement pour saisir les opportunités, réduire les menaces et construire un <b>avantage concurrentiel</b>. Le PESTEL alimente la partie externe du <b>SWOT</b> (thème 6).</p>`,
[["Dans PESTEL, le « L » signifie…", ["légal", "logistique", "local", "leadership"], "Les lois et règlements."], ["Le RGPD est un facteur…", ["légal", "socioculturel", "écologique", "technologique"], "Règlement européen."], ["La généralisation du télétravail est un facteur…", ["socioculturel", "politique", "légal", "écologique"], "Évolution des modes de vie et de travail."], ["Un environnement difficile à prévoir est dit…", ["incertain", "stable", "simple", "monopolistique"], "Instable, incertain, complexe."], ["Le PESTEL alimente quelle partie du SWOT ?", ["opportunités et menaces", "forces et faiblesses", "aucune", "uniquement les forces"], "C'est un diagnostic externe."]],
[{ id: "e8a", niv: 2, titre: "Réaliser un PESTEL", q: "Réalisez un PESTEL (un élément par facteur) pour une PME française qui développe des logiciels de gestion pour les cabinets médicaux, en précisant s'il s'agit d'une opportunité ou d'une menace.", c: `${OUT.T(["Facteur", "Élément", "O/M"], [["Politique", "plan public de numérisation de la santé", "opportunité"], ["Économique", "budgets serrés des cabinets, inflation", "menace"], ["Socioculturel", "patients habitués à la prise de rendez-vous et à la téléconsultation en ligne", "opportunité"], ["Technologique", "IA d'aide à la saisie, mais aussi cyberattaques contre la santé", "opportunité / menace"], ["Écologique", "exigence de sobriété numérique", "menace (coûts) ou opportunité (argument commercial)"], ["Légal", "RGPD et hébergement certifié HDS des données de santé", "menace (coût de conformité), opportunité face à des concurrents non conformes"]])}` }]);

/* =================================================================== THÈME 3 */
CH(3, "Choix de production", "Les facteurs déterminants des choix de production", "Travail, capital, coûts, productivité, combinaison productive, chaîne de valeur, externalisation.", `
<h3>1. Les facteurs de production</h3>
<ul><li><b>Le travail</b> : aspect quantitatif (population active, durée du travail) et qualitatif (qualification, <b>capital humain</b>).</li><li><b>Le capital</b> : moyens matériels (machines, bâtiments, serveurs). Il s'use mais s'accumule par l'<b>investissement</b> : de <b>capacité</b> (produire plus), de <b>renouvellement</b> (remplacer l'obsolète), de <b>productivité</b> (produire mieux et moins cher).</li></ul>
<h3>2. Coûts et productivité</h3>
${T(["Coûts", "Définition", "Exemples"], [["Fixes", "indépendants du volume produit", "loyer, amortissements, licences annuelles"], ["Variables", "varient avec la production", "matières, énergie, hébergement à l'usage"], ["Directs", "imputables directement à un produit", "temps des développeurs sur un projet"], ["Indirects", "à répartir entre produits", "frais administratifs, assurances"]])}
<p>Répartir les coûts fixes sur un volume plus grand donne des <b>économies d'échelle</b>.</p>
${box("Productivité", "<b>Productivité = quantité produite / quantité de facteur utilisée.</b> Productivité horaire apparente du travail = production / heures travaillées.")}
<h3>3. La combinaison productive</h3>
<p>C'est la proportion de capital et de travail utilisée. Les facteurs sont <b>complémentaires</b> (il faut les deux) et souvent <b>substituables</b> (remplacer des hommes par des machines, ou l'inverse). Le choix dépend du <b>coût relatif</b> du travail et du capital, des <b>taux d'intérêt</b> (coût de l'emprunt pour investir), du besoin de qualification et de la nature de l'activité (les services sont moins automatisables).</p>
<h3>4. La chaîne de valeur (Porter)</h3>
<p><b>Activités principales</b> (logistique, production, commercialisation, services) et <b>activités de soutien</b> (infrastructure, GRH, développement technologique, approvisionnements). L'analyser permet de savoir où l'entreprise crée de la valeur et ce qu'elle peut confier à d'autres : <b>chaîne de valeur mondiale</b>.</p>
<h3>5. Faire ou faire faire ?</h3>
${T(["Forme d'impartition", "Principe"], [["<b>Externalisation</b>", "confier à un prestataire une activité hors du cœur de métier (infogérance, paie, cloud)"], ["<b>Sous-traitance</b>", "confier une partie de sa production à une autre entreprise"], ["<b>Franchise</b>", "le franchiseur cède l'usage de sa marque et de son savoir-faire contre un droit d'entrée et des redevances"], ["<b>Concession</b>", "le concessionnaire distribue les produits d'un concédant"], ["<b>Coentreprise</b> (joint-venture)", "société commune pour un projet, souvent à l'étranger"], ["<b>GIE</b>", "groupement pour mener un projet commun ou réduire des coûts"]])}
<p><b>Avantages :</b> baisse des coûts, compétences et qualité, flexibilité, rapidité, <b>recentrage sur le cœur de métier</b>. <b>Risques :</b> dépendance, perte de contrôle et de savoir-faire, confidentialité des données, qualité moins maîtrisée.</p>`,
[["Remplacer des salariés par des machines, c'est…", ["substituer du capital au travail", "substituer du travail au capital", "externaliser", "sous-traiter"], "La combinaison productive évolue."], ["Un loyer est un coût…", ["fixe", "variable", "direct", "marginal"], "Il ne dépend pas du volume produit."], ["Productivité du travail =", ["production / heures travaillées", "heures / production", "chiffre d'affaires − charges", "capital / travail"], "Plus elle est élevée, plus le travail est efficace."], ["Confier la gestion de son parc informatique à une ESN, c'est…", ["de l'externalisation (infogérance)", "une franchise", "une concession", "une fusion"], "On se recentre sur le cœur de métier."], ["Dans la chaîne de valeur de Porter, la GRH est une activité…", ["de soutien", "principale", "externe", "facultative"], "Elle soutient les activités principales."], ["Les économies d'échelle viennent de…", ["la répartition des coûts fixes sur un plus grand volume", "la hausse des salaires", "la baisse de la production", "l'inflation"], "Le coût unitaire baisse."]],
[{ id: "e9a", niv: 2, titre: "Externaliser ou non ?", q: "Une PME de 60 salariés hésite à confier son support informatique et son hébergement à une ESN. Présentez les avantages et les risques, puis donnez votre avis argumenté.", c: "<p><b>Avantages :</b> compétences pointues, disponibilité 24/7, coût variable et prévisible, recentrage sur le cœur de métier, mises à jour et sécurité assurées par un spécialiste.</p><p><b>Risques :</b> dépendance au prestataire, perte de compétences internes, confidentialité et localisation des données (RGPD), réactivité moindre, coût à long terme.</p><p><b>Avis :</b> externaliser l'hébergement et le support de niveau 1 peut être pertinent, à condition de signer un contrat avec des niveaux de service (SLA), des clauses de confidentialité et de réversibilité, et de garder un référent interne.</p>" },
 { id: "e9b", niv: 1, titre: "Calculer une productivité", q: "En janvier, 5 techniciens traitent 1 500 tickets en 750 heures. En février, avec un nouvel outil de ticketing, 5 techniciens traitent 1 800 tickets en 720 heures. Calculez la productivité horaire et son évolution.", c: "<p>Janvier : 1 500 / 750 = <b>2 tickets/heure</b>. Février : 1 800 / 720 = <b>2,5 tickets/heure</b>. Évolution : (2,5 − 2) / 2 × 100 = <b>+25 %</b>. L'outil (investissement de productivité) a permis un gain de productivité.</p>" }]);

CH(3, "Structures juridiques", "Le choix d'une structure juridique pour entreprendre", "EI, EURL, SARL, SAS, SA, statut du dirigeant, IR/IS, SCOP, mutuelles.", `
<h3>1. L'entreprise individuelle (EI)</h3>
<p>L'entrepreneur exerce seul, sans capital social, avec des formalités simples. L'EI n'a <b>pas de personnalité juridique</b> distincte. Depuis la loi du 14 février 2022 (en vigueur le 15 mai 2022), le patrimoine professionnel est <b>automatiquement séparé</b> du patrimoine personnel : les créanciers professionnels ne peuvent saisir que les biens utiles à l'activité (sauf fraude ou renonciation). L'EIRL ne peut plus être créée. La résidence principale est insaisissable par les créanciers professionnels. La <b>micro-entreprise</b> est un régime simplifié de l'EI.</p>
${box("Attention", "Ton cours présente encore l'EIRL et la déclaration d'insaisissabilité devant notaire : ces dispositifs ont été remplacés par la réforme de 2022. Cite plutôt la séparation automatique des patrimoines.", "warn")}
<h3>2. Les sociétés</h3>
<p>Une société a la <b>personnalité morale</b> et un patrimoine propre : les associés ne répondent des dettes qu'à hauteur de leurs <b>apports</b> (sauf faute de gestion du dirigeant).</p>
${T(["Forme", "Associés", "Capital", "Dirigeant", "Statut social du dirigeant"], [["<b>EURL</b>", "1", "libre (1 € possible)", "gérant", "TNS si associé unique gérant"], ["<b>SARL</b>", "2 à 100", "libre", "gérant", "TNS si gérant majoritaire, assimilé salarié si minoritaire"], ["<b>SASU / SAS</b>", "1 ou plus", "libre", "président (statuts très libres)", "assimilé salarié"], ["<b>SA</b>", "2 minimum (7 si cotée)", "37 000 € minimum", "conseil d'administration, directeur général", "assimilé salarié"]])}
<p>Seule la <b>SA</b> (ou la SCA) peut faire une offre au public de titres en Bourse. Les start-up choisissent souvent la <b>SAS</b> pour sa souplesse (entrée d'investisseurs, actions de préférence).</p>
<h3>3. Statut social et fiscal</h3>
<ul><li><b>TNS</b> (travailleur non salarié) : cotisations plus faibles, protection sociale moindre.</li><li><b>Assimilé salarié</b> : protection proche des salariés (sauf assurance chômage), cotisations plus élevées.</li><li><b>Impôt sur le revenu (IR)</b> : le bénéfice est imposé au nom de l'entrepreneur, au barème progressif (jusqu'à 45 %).</li><li><b>Impôt sur les sociétés (IS)</b> : 15 % jusqu'à 42 500 € de bénéfice pour les PME, puis 25 % ; les associés ne sont imposés que sur les dividendes reçus. Plus intéressant quand le bénéfice augmente.</li></ul>
<h3>4. L'économie sociale et solidaire (ESS)</h3>
<ul><li><b>SCOP</b> : société coopérative (forme SA, SARL ou SAS) dont les <b>salariés sont associés majoritaires</b> (au moins 51 % du capital et 65 % des droits de vote) ; principe « <b>une personne = une voix</b> » ; une part importante des bénéfices va aux réserves et aux salariés.</li><li><b>Mutuelle</b> : groupement à but non lucratif, gestion démocratique par les adhérents, actions de prévoyance et de solidarité.</li><li>Autres : associations, SCIC, fondations.</li></ul>`,
[["Une SAS est dirigée par…", ["un président", "un gérant", "un conseil de surveillance obligatoire", "un mandataire judiciaire"], "Les statuts sont très libres."], ["Quelle forme permet de lever des fonds en Bourse ?", ["la SA", "la SARL", "l'EURL", "l'EI"], "Offre au public de titres."], ["Dans une société, la responsabilité des associés est en principe limitée…", ["à leurs apports", "à leur patrimoine personnel", "à 1 €", "à 37 000 €"], "La société a un patrimoine propre."], ["Le gérant majoritaire de SARL a le statut…", ["de travailleur non salarié", "d'assimilé salarié", "de fonctionnaire", "de salarié"], "Le président de SAS est assimilé salarié."], ["Le taux normal de l'IS est de…", ["25 %", "33,3 %", "45 %", "15 %"], "15 % sur la première tranche pour les PME."], ["Dans une SCOP, le vote suit le principe…", ["une personne = une voix", "une action = une voix", "le dirigeant décide seul", "vote des clients"], "Principe coopératif."], ["Depuis 2022, l'entrepreneur individuel…", ["a son patrimoine professionnel séparé automatiquement", "doit créer une EIRL", "répond sur tous ses biens", "doit avoir 37 000 € de capital"], "Loi du 14 février 2022."]],
[{ id: "e10a", niv: 2, titre: "Conseiller une forme juridique", q: "Trois amis développeurs veulent créer une start-up d'applications mobiles. Ils prévoient de faire entrer des investisseurs dans deux ans et veulent une bonne protection sociale. Quelle forme juridique conseillez-vous ? Justifiez.", c: "<p>La <b>SAS</b> : plusieurs associés possibles ; responsabilité limitée aux apports ; statuts très libres (répartition des pouvoirs, clauses d'agrément et d'entrée d'investisseurs, actions de préférence) ; le président a le statut d'<b>assimilé salarié</b> (meilleure protection sociale) ; soumise à l'IS. La SARL est plus rigide pour l'entrée d'investisseurs ; la SA est trop lourde (capital de 37 000 €, conseil d'administration).</p>" }]);

CH(3, "Responsabilité de l'entreprise", "La gestion des risques inhérents à l'activité de l'entreprise", "Responsabilité pénale, civile contractuelle et extracontractuelle, produits défectueux.", `
<h3>1. Responsabilité pénale et civile</h3>
${T(["", "Responsabilité pénale", "Responsabilité civile"], [["But", "<b>punir</b> l'auteur d'une infraction", "<b>réparer</b> le dommage causé"], ["Principe", "légalité des délits et des peines : l'acte doit être défini par la loi", "tout dommage causé à autrui doit être réparé"], ["Sanction", "amende, prison (personnes physiques), dissolution, exclusion des marchés publics", "dommages-intérêts"]])}
<p>Depuis 1994, les <b>personnes morales</b> sont pénalement responsables (art. 121-2 C. pén.) des infractions commises pour leur compte par leurs organes ou représentants ; cette responsabilité peut se cumuler avec celle du dirigeant.</p>
<h3>2. La responsabilité civile contractuelle</h3>
<p>Elle suppose un contrat entre l'auteur et la victime. Conditions (art. 1231-1 C. civ.) : <b>inexécution</b> d'une obligation du contrat, <b>dommage</b>, <b>lien de causalité</b>, après <b>mise en demeure</b>.</p>
<ul><li><b>Obligation de résultat</b> : la seule absence de résultat engage le débiteur (transporteur, obligation de sécurité de l'employeur).</li><li><b>Obligation de moyens</b> : le créancier doit prouver que le débiteur n'a pas tout mis en œuvre (un conseil, une maintenance où le client a un rôle actif).</li></ul>
<p>Moyens de défense : <b>clauses limitatives</b> (sans effet si elles vident l'obligation essentielle — art. 1170 — ou en cas de faute lourde ou dolosive — art. 1231-3), <b>force majeure</b>, <b>assurance</b> responsabilité civile (transfert du risque).</p>
<h3>3. La responsabilité civile extracontractuelle (délictuelle)</h3>
<p>Elle s'applique quand il n'y a <b>pas de contrat</b> entre l'auteur et la victime (règle du <b>non-cumul</b>). Trois conditions : un <b>fait générateur</b>, un <b>dommage</b>, un <b>lien de causalité</b>.</p>
${T(["Fait générateur", "Article"], [["fait personnel (faute intentionnelle ou d'imprudence)", "art. 1240 et 1241 C. civ."], ["fait des choses dont on a la garde", "art. 1242 al. 1"], ["fait d'autrui : l'employeur répond de ses salariés (commettants et préposés)", "art. 1242 al. 5"], ["produits défectueux", "art. 1245 et suivants"]])}
<p>Exonération : force majeure, fait d'un tiers ou faute de la victime (totale si elle a les caractères de la force majeure, partielle sinon).</p>
<h3>4. Les produits défectueux (art. 1245)</h3>
<p>Le producteur est responsable du dommage causé par un produit qui n'offre pas la <b>sécurité à laquelle on peut légitimement s'attendre</b>, que la victime soit ou non liée à lui par un contrat. La victime prouve le défaut, le dommage (atteinte à la personne ou à un autre bien que le produit) et le lien de causalité. Exonération possible notamment pour <b>risque de développement</b> (défaut indécelable selon l'état des connaissances au moment de la mise en circulation).</p>`,
[["La responsabilité civile a pour but de…", ["réparer un dommage", "punir", "dissoudre l'entreprise", "fixer un impôt"], "La responsabilité pénale punit."], ["Une société peut-elle être pénalement responsable ?", ["Oui, depuis 1994 (art. 121-2 C. pén.)", "Non, jamais", "Seulement une SA", "Seulement si le dirigeant est absent"], "Infraction commise pour son compte par ses organes."], ["Un piéton blessé par un véhicule de livraison d'une entreprise agit sur le fondement de la responsabilité…", ["extracontractuelle", "contractuelle", "pénale uniquement", "du fait des produits défectueux"], "Il n'a pas de contrat avec l'entreprise."], ["L'employeur répond des dommages causés par ses salariés dans leurs fonctions en vertu de…", ["l'art. 1242 al. 5 C. civ.", "l'art. 1128 C. civ.", "l'art. L. 420-1 C. com.", "l'art. 1137 C. civ."], "Responsabilité du commettant du fait du préposé."], ["Une clause limitative de responsabilité est sans effet en cas de…", ["faute lourde ou dolosive", "simple retard", "accord des parties", "contrat écrit"], "Art. 1231-3 du Code civil."], ["Le risque de développement permet au producteur de…", ["s'exonérer si le défaut était indécelable", "augmenter ses prix", "rompre le contrat", "déposer un brevet"], "Responsabilité du fait des produits défectueux."]],
[{ id: "e11a", niv: 3, titre: "Contractuelle ou délictuelle ?", q: "Un technicien d'une société de maintenance, en intervention chez un client, renverse par imprudence une baie de serveurs : le client perd ses serveurs, et un visiteur présent est blessé. Sur quels fondements le client et le visiteur peuvent-ils agir contre la société de maintenance ?", c: "<p><b>Le client</b> est lié par un contrat de maintenance : il agit en <b>responsabilité contractuelle</b> (art. 1231-1 C. civ.) : inexécution (obligation d'intervenir sans causer de dommage), dommage (serveurs détruits, perte d'exploitation), lien de causalité. Une éventuelle clause limitative ne jouerait pas en cas de faute lourde.</p><p><b>Le visiteur</b> n'a aucun contrat avec la société : il agit en <b>responsabilité extracontractuelle</b>, sur le fondement de la responsabilité de l'employeur du fait de son salarié (<b>art. 1242 al. 5</b>) : le technicien a commis une faute d'imprudence dans l'exercice de ses fonctions ; dommage corporel ; lien de causalité. La société indemnise (elle se tourne vers son assurance RC).</p>" }]);

CH(3, "Organisation et management", "L'organisation des ressources dans l'entreprise", "Processus, ressources, compétences, structures, coordination (Mintzberg), styles de direction, niveaux de décision.", `
<h3>1. Processus, ressources et compétences</h3>
<p>Un <b>processus</b> est un ensemble d'activités reliées par des flux (informations, matières) qui produit un résultat pour un client. L'AFNOR distingue les processus de <b>réalisation</b> (opérationnels), de <b>support</b> et de <b>pilotage</b>. Les <b>processus clés</b> fondent l'avantage concurrentiel.</p>
<ul><li><b>Ressources tangibles</b> (locaux, machines, stocks, effectifs, trésorerie) et <b>intangibles</b> (marque, réputation, brevets, savoir-faire, culture d'entreprise, données) — distinction d'Edith Penrose. Les intangibles fondent souvent des avantages durables.</li><li><b>Compétences individuelles</b> : savoirs, savoir-faire, savoir-être ; elles se développent par la formation, l'expérience (<i>learning by doing</i>), la mobilité. <b>Compétences collectives</b> : capacité à coopérer et à faire fonctionner l'organisation.</li><li>L'<b>effet d'expérience</b> : plus on produit, plus on apprend et plus le coût unitaire baisse.</li></ul>
<h3>2. Les structures</h3>
${T(["Structure", "Découpage", "Avantages", "Limites"], [["<b>Fonctionnelle</b>", "par fonction (production, commercial, finance, DSI)", "spécialisation, économies", "cloisonnement, lenteur"], ["<b>Divisionnelle</b>", "par produit, marché ou zone géographique", "proximité du marché, autonomie", "doublons de fonctions, coûts"], ["<b>Matricielle</b>", "double rattachement (fonction + projet ou division)", "souplesse, coopération", "conflits de pouvoir (deux chefs)"], ["<b>Par projet / en réseau</b>", "équipes temporaires, partenaires", "réactivité, autonomie", "coordination difficile"]])}
<p>Il n'existe pas de structure idéale : elle dépend du contexte (<b>théorie de la contingence</b>).</p>
<h3>3. Les mécanismes de coordination (Mintzberg)</h3>
${T(["Mécanisme", "Exemple"], [["<b>Ajustement mutuel</b>", "communication informelle dans une petite équipe agile"], ["<b>Supervision directe</b>", "le chef donne les consignes"], ["Standardisation des <b>procédés</b>", "procédures ITIL, processus de ticketing"], ["Standardisation des <b>résultats</b>", "objectifs chiffrés, SLA"], ["Standardisation des <b>qualifications</b>", "diplômes, certifications (CCNA…)"], ["Standardisation des <b>normes</b>", "valeurs et culture partagées"]])}
<h3>4. Diriger</h3>
<p>Diriger, c'est « obtenir des résultats par d'autres », en équilibrant autorité et autonomie. Styles de direction (Likert) : <b>autoritaire</b> (décisions seules, peu de communication), <b>paternaliste</b> (récompenses et sanctions, quelques délégations), <b>consultatif</b> (on consulte sans vraiment partager la décision), <b>participatif</b> (décisions en groupe, contrôle décentralisé).</p>
${T(["Décision", "Horizon et risque", "Qui ?", "Exemple"], [["<b>Stratégique</b>", "long terme, risquée, peu réversible", "direction générale", "fusion, nouvelle activité"], ["<b>Tactique</b>", "moyen terme, réversible", "managers intermédiaires", "budget formation, campagne publicitaire"], ["<b>Opérationnelle</b>", "court terme, très réversible", "personnel de terrain", "commande, planning du support"]])}`,
[["Une structure où un salarié a deux responsables (métier et projet) est…", ["matricielle", "fonctionnelle", "divisionnelle", "hiérarchique simple"], "Double rattachement."], ["Pour Mintzberg, la coordination par la communication informelle est…", ["l'ajustement mutuel", "la supervision directe", "la standardisation des résultats", "la standardisation des normes"], "Typique des petites équipes."], ["Une marque et une réputation sont des ressources…", ["intangibles", "tangibles", "financières", "matérielles"], "Elles fondent des avantages durables."], ["Décider d'une fusion est une décision…", ["stratégique", "tactique", "opérationnelle", "courante"], "Long terme, risquée, peu réversible."], ["La théorie de la contingence dit que…", ["la bonne structure dépend du contexte", "la structure matricielle est toujours la meilleure", "il faut toujours centraliser", "la taille ne compte pas"], "Pas de modèle universel."], ["Des certifications exigées à l'embauche illustrent la standardisation des…", ["qualifications", "procédés", "résultats", "normes"], "On coordonne par les compétences acquises."]],
[{ id: "e12a", niv: 2, titre: "Identifier une structure et sa coordination", q: "Une ESN de 300 salariés a trois agences (Paris, Lyon, Nantes) ; chaque agence a ses commerciaux, ses développeurs et son support. Les techniciens suivent des procédures ITIL et ont des objectifs de délai de résolution. Identifiez la structure et les mécanismes de coordination.", c: "<p><b>Structure divisionnelle géographique</b> : découpage par zone, chaque agence regroupe les fonctions. Avantages : proximité des clients, réactivité ; limites : doublons, coûts.</p><p><b>Coordination</b> : standardisation des <b>procédés</b> (procédures ITIL) et des <b>résultats</b> (objectifs de délai, SLA) ; probablement aussi ajustement mutuel au sein des équipes.</p>" }]);

CH(3, "Financement", "Le financement de l'entreprise", "Bilan, compte de résultat, FRNG, BFR, trésorerie, autofinancement, emprunt, crédit-bail.", `
<h3>1. Les documents de synthèse</h3>
<ul><li>Le <b>bilan</b> décrit le patrimoine à une date : <b>actif</b> (ce que l'entreprise possède : immobilisations, stocks, créances, trésorerie) et <b>passif</b> (ressources : capitaux propres, dettes).</li><li>Le <b>compte de résultat</b> retrace l'activité d'un exercice : <b>Résultat = produits − charges</b> (bénéfice ou perte).</li></ul>
${box("Les 3 indicateurs de l'équilibre financier", "<b>FRNG</b> (fonds de roulement) = ressources stables − emplois stables : excédent des ressources à long terme qui finance l'exploitation.<br><b>BFR</b> (besoin en fonds de roulement) = stocks + créances clients − dettes fournisseurs (exploitation).<br><b>Trésorerie nette = FRNG − BFR.</b> Si elle est négative, l'entreprise dépend du découvert.")}
<h3>2. Financer l'exploitation</h3>
<p>Le <b>BFR</b> naît des décalages : les clients paient après la vente, les stocks sont payés avant d'être vendus. Solutions : <b>découvert</b> (rapide mais coûteux), utiliser le <b>fonds de roulement</b> (apports, emprunts), <b>affacturage</b> (céder ses créances à un factor contre une commission), escompte.</p>
<p>Réduire le BFR : <b>raccourcir les délais clients</b>, <b>allonger les délais fournisseurs</b> (dans la limite légale : en principe 60 jours après facture ou 45 jours fin de mois), <b>réduire les stocks</b> (juste-à-temps).</p>
<h3>3. Financer l'investissement</h3>
<p>Types d'investissement : de <b>capacité</b>, de <b>modernisation</b> (ou renouvellement), de <b>productivité</b> ; plus les investissements immatériels (R&D, logiciels, formation).</p>
${T(["Mode", "Avantages", "Inconvénients"], [["<b>Autofinancement</b> (bénéfices mis en réserve)", "indépendance, pas de coût d'intérêt", "limité aux entreprises rentables"], ["<b>Augmentation de capital</b>", "fonds propres, pas de remboursement", "dilution du pouvoir, dividendes attendus"], ["<b>Emprunt</b>", "pas de dilution, effet de levier", "intérêts, remboursements, endettement"], ["<b>Crédit-bail</b> (location avec option d'achat)", "pas d'apport, matériel renouvelé (véhicules, serveurs)", "coût total élevé, pas propriétaire avant la levée de l'option"], ["<b>Financements alternatifs</b>", "crowdfunding, business angels, capital-risque, subventions, prêts Bpifrance", "sélectifs ou dilutifs"]])}`,
[["Trésorerie nette =", ["FRNG − BFR", "BFR − FRNG", "actif − passif", "produits − charges"], "Relation fondamentale."], ["Accorder des délais de paiement plus longs aux clients…", ["augmente le BFR", "diminue le BFR", "n'a aucun effet", "augmente le FRNG"], "Les créances clients augmentent."], ["Le résultat d'un exercice figure dans…", ["le compte de résultat (et au passif du bilan)", "le registre RGPD", "le Kbis", "la liasse sociale uniquement"], "Produits − charges."], ["Céder ses factures clients à un organisme pour être payé tout de suite, c'est…", ["l'affacturage", "le crédit-bail", "l'autofinancement", "l'augmentation de capital"], "Contre une commission."], ["Le mode de financement qui dilue le pouvoir des associés est…", ["l'augmentation de capital", "l'emprunt", "l'autofinancement", "le découvert"], "De nouveaux associés entrent."], ["Le crédit-bail est…", ["une location avec option d'achat", "un prêt sans intérêt", "un don de l'État", "une émission d'obligations"], "Adapté aux biens renouvelés souvent."]],
[{ id: "e13a", niv: 1, titre: "Calculer FRNG, BFR, trésorerie", q: "Une ESN a : capitaux propres 300 k€, emprunts à long terme 200 k€, immobilisations 380 k€, stocks 10 k€, créances clients 260 k€, dettes fournisseurs et fiscales 150 k€. Calculez le FRNG, le BFR et la trésorerie nette. Commentez.", c: "<p>FRNG = (300 + 200) − 380 = <b>120 k€</b>. BFR = 10 + 260 − 150 = <b>120 k€</b>. Trésorerie nette = 120 − 120 = <b>0 €</b>.</p><p>Le fonds de roulement couvre juste le BFR : l'équilibre est fragile. Le poste clé est la créance clients (260 k€) : relancer les clients, réduire les délais de paiement ou recourir à l'affacturage.</p>" }]);
})();
